import json,base64,re
V='1'
css=open('base.css').read()
logo='logo.png?v='+V
loads=[l.strip() for l in open('/workspace/waybill/old-load-list.txt') if l.strip()]
assert len(loads)==48
js=open('app.src.js').read().replace('__TERMS__',open('terms.json').read()).replace('__LOADS__',json.dumps(loads)).replace('__V__',V)
open('app.js','w').write(js)
EXTRA='''
main{max-width:1200px;width:100%;margin:0 auto;padding:16px}
.sbar{background:#8f8f8a;color:#fff;font-weight:700;font-size:15px;padding:9px 14px;border-radius:6px;display:flex;align-items:center;gap:10px;margin:18px 0 10px;flex-wrap:wrap}.sbar>span:first-child{flex:1}
.fg{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px 16px}.fg label,.lbl2{display:block;font-size:12.5px;font-weight:700;margin-bottom:4px}
.inp{border:1px solid #cfcfca;border-radius:6px;padding:7px 9px;background:#fff;font-size:14px;min-height:36px;width:100%;font-family:inherit}
td .inp{width:auto}.calc{font-weight:700;padding:8px 0}.vis{font-size:12px;color:var(--grey)}
table.grid{border-collapse:collapse;width:100%;font-size:13px}table.grid th,table.grid td{padding:7px 8px;border-bottom:1px solid var(--line);text-align:left}table.grid th{background:#2A2A27;color:#fff}.num{text-align:right!important}
.tw{overflow-x:auto;-webkit-overflow-scrolling:touch}.btn.sm{padding:5px 10px;font-size:12.5px}
.del{display:inline-flex;width:30px;height:28px;border-radius:5px;background:var(--red);color:#fff;align-items:center;justify-content:center;cursor:pointer}
.mback{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:50;align-items:center;justify-content:center}.mback.on{display:flex}.mbox{background:#fff;border-radius:10px;padding:18px 20px;width:640px;max-width:94vw;max-height:88vh;overflow:auto;border-top:4px solid var(--red)}.mbox h3{margin:0 0 10px}.mbox label{display:block;font-weight:700;margin:10px 0 4px}
.row{display:flex;gap:10px;align-items:center;margin-top:12px;flex-wrap:wrap}.row .spacer{flex:1}
.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);background:var(--ink);color:#fff;padding:12px 18px;border-radius:8px;font-weight:700;opacity:0;transition:.2s;z-index:60;pointer-events:none;max-width:92vw;text-align:center}.toast.on{opacity:1}
.llist{max-height:280px;overflow:auto;border:1px solid var(--line);border-radius:6px;margin-top:8px;display:grid;grid-template-columns:1fr 1fr}.llist a{padding:8px 10px;border-bottom:1px solid var(--line);text-decoration:none;color:var(--ink)}.llist a:hover{background:#fde4e2}
.sigw{border:1px dashed #999;border-radius:6px;background:#fff;position:relative}canvas.sig{width:100%;height:120px;touch-action:none;display:block}.clr{position:absolute;right:6px;top:6px}
.stop{display:grid;grid-template-columns:auto 1fr 1fr auto;gap:8px;align-items:center;margin:6px 0}
#stampprev img{max-width:220px;max-height:160px;border:1px solid var(--line);margin-top:8px}
.tabs{display:flex;gap:4px;border-bottom:2px solid var(--line);margin:10px 0;overflow-x:auto}.tabs a{padding:8px 14px;text-decoration:none;color:var(--grey);font-weight:700;white-space:nowrap}.tabs a.on{color:var(--red-dark);border-bottom:3px solid var(--red)}
.terms h2{text-align:center;font-size:15px;margin:0 0 10px}.terms ol{padding-left:28px;margin:0}.terms li{font-size:12.5px;line-height:1.35;margin-bottom:10px;padding-left:14px}
.actions{position:sticky;bottom:0;background:#fff;border-top:1px solid var(--line);padding:10px;display:flex;gap:8px;flex-wrap:wrap;margin-top:18px;z-index:5}
.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px}.card2{background:#fff;border:1px solid var(--line);border-radius:10px;padding:16px;text-decoration:none;color:var(--ink);border-top:4px solid var(--red)}.card2 b{font-size:16px}
.ftab label{display:inline-flex;gap:6px;margin-right:12px;font-weight:600}
@media(max-width:700px){.nav{display:none}.topbar{padding:8px 12px}.brand img{height:32px}main{padding:10px}.stop{grid-template-columns:1fr}.llist{grid-template-columns:1fr}}
'''
NOCACHE='<meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate"><meta http-equiv="Pragma" content="no-cache"><meta http-equiv="Expires" content="0">'
def page(fn,title,body,active='',extra=''):
    nav=''.join(f'<a href="{h}?v={V}"{" class=active" if n==active else ""}>{n}</a>' for n,h in [('Jobs','job-214.html'),('Forms','forms-waybill.html'),('Reports','report.html')])
    h=f'''<!DOCTYPE html><html><head><meta charset="utf-8">{NOCACHE}<meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Rig Runner Tracker</title><style>{css}{EXTRA}{extra}</style></head><body>
<header class="topbar"><a class="brand" href="index.html?v={V}"><img src="{logo}" alt="Rig Runner"><span class="divider"></span><span class="appname">Tracker</span></a><nav class="nav">{nav}</nav><span class="spacer"></span><span class="demo-badge">Mockup · sample data</span></header>
<main>{body}</main><footer class="appfoot">© Rig Runner 2026 · Waybill mockup — fake data only</footer>
<div class=toast id=toast></div><div id=modal class=mback><div class=mbox><h3 id=mt></h3><div id=mf></div><div class=row><span class=spacer></span><span class=btn id=mc>Close</span><span class="btn primary" id=mo>OK</span></div></div></div><script src="app.js?v={V}"></script></body></html>'''
    open(fn,'w').write(h)
F=lambda lab,inner,cls='':f'<div class="{cls}"><label>{lab}</label>{inner}</div>'
I=lambda i,ph='',t='text',v='':f'<input class=inp id={i} type={t} placeholder="{ph}" value="{v}">'
S=lambda i:f'<select class=inp id={i}></select>'
def blk(p,t):
    return f'<div><div class=lbl2 style="font-size:14px">{t}</div><div class=fg>'+F('Company',f'<select class="inp s_co" id={p}_co></select>')+F('Rig #',f'<select class="inp s_rig" id={p}_rig></select>')+F('Oil Co. (operator)',f'<select class="inp s_op" id={p}_op></select>')+F('Well #',I(p+'_well','Free text'))+F('City / State / Zip',I(p+'_city','e.g. Odessa, TX 79761'))+'</div></div>'
def form(A):
    b=f'<form id=wbform data-mode="{"A" if A else "B"}" onsubmit="return false">'
    b+='<div class=sbar><span>'+('New Waybill — Rig Move (Job #214)' if A else 'Waybill — Standalone Driver Form')+'</span><span style="font-weight:400">Load # <b id=loadno style="color:#fff;font-size:18px"></b> (auto)</span><a href=# class="viewterms" style="color:#fff">View terms and conditions</a></div>'
    b+='<div class=fg>'+F('Date',I('f_date',t='date'))+(F('Job #','<input class=inp value="214" readonly>') if A else '')+F("Shipper's BOL # (optional)",I('f_sbol'))+F("Shipper's Order # (optional)",I('f_sord'))+F("Consignee's BOL # (optional)",I('f_cbol'))+F("Consignee's Order # (optional)",I('f_cord'))+F('PPE Required','<label style="font-weight:600"><input type=checkbox id=f_ppe> PPE required</label>')+'</div>'
    b+='<div class=sbar><span>Driver &amp; Equipment</span></div><div class=fg>'+F('Driver',S('f_driver')+'<div class=vis>Defaults to the operator linked to the truck / signed-in driver</div>')+F('Swamper (optional)',S('f_swamper'))+F('Truck (equipment list)',S('f_truck'))+F('Trailer (equipment list)',S('f_trailer'))+F('Equipment Type','<input class=inp id=f_eqtype readonly>')+F('Equipment Ordered By',I('f_eqby','Free text'))+'</div>'
    if A: b+='<div class=sbar><span>Ends (from job)</span></div><div class=fg>'+F('Old End',I('f_old',v='Sample Lease #4H — Pecos, TX'))+F('New End',I('f_new',v='Sample Ranch Unit 12 #1 — Monahans, TX'))+'</div>'
    else: b+='<div class=sbar><span>Shipper &amp; Consignee</span></div><div class=fg style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))">'+blk('s','Shipper')+blk('c','Consignee')+'</div>'
    b+='<div class=sbar><span>Trip</span></div><div class=fg>'+F('Origination (clock-in town)',I('f_orig'))+F('Destination (clock-out town)',I('f_dest'))+F('Start Odometer',I('f_odo1',t='number'))+F('End Odometer',I('f_odo2',t='number'))+F('Miles (calculated)','<div class=calc id=f_miles>—</div>')+F('Start Time (clock-in)',I('f_t1',t='time'))+F('End Time (clock-out)',I('f_t2',t='time'))+'</div><div class=vis id=samsara></div>'
    b+='<div style="margin-top:10px"><label class=lbl2>Route (origination → destination)</label><textarea class=inp id=f_route rows=2 placeholder="e.g. I-20 W to Pecos, FM 1450 N to lease; return TX-18"></textarea></div>'
    b+='<div class=sbar><span>Loads <span class=vis style="color:#fff" id=lsum></span></span><span class="btn sm dark" id=addload>⊕ Add Load</span></div><div class=tw><table class=grid id=loads><thead><tr><th>Qty</th><th>X=HM</th><th>Description</th><th>Weight</th><th>L</th><th>W</th><th>H</th><th>Hours/Miles</th><th>Equip/Rate</th><th>Amount</th><th></th></tr></thead><tbody></tbody></table></div>'
    b+='<div class=sbar><span>Bill To</span>'+('' if A else '<a href=# id=billreq style="color:#fff">View billing requirements</a>')+'</div><div class=fg>'+(F('Bill To (from job)','<input class=inp id=f_bill readonly>') if A else F('Bill To customer',S('f_cust')))+F('Freight Payment Terms','<div class=ftab>'+''.join(f'<label><input type=radio name=ft value="{x}">{x}</label>' for x in ['Prepaid','Collect','Third Party','C.O.D.'])+'</div>')+'</div>'
    b+='<div class=sbar><span>HazMat</span></div><div class=fg>'+F('HazMat Emergency Contact No.',I('f_haz1','(000) 000-0000','tel'))+F('Hazmat Name or Contract No.',I('f_haz2'))+'</div>'
    if not A:
        b+='<div class=sbar><span>Charges <span class=vis style="color:#fff">(optional for driver · editable by management)</span></span></div><div class=fg>'+''.join(F(n,f'<input class="inp chg" data-k={k} inputmode=decimal placeholder="0.00">') for k,n in [('pm','Permits'),('lh','Line Haul'),('ins','Insurance Surcharge'),('fs','Fuel Surcharge'),('af','Access Fuel'),('dt','Detention Time'),('es','Extra Stops')])+F('Total (calculated)','<div class=calc id=f_total>$0.00</div>')+'</div>'
    b+='<div class=sbar><span>Extra Stops &amp; Detention</span><span class="btn sm dark" id=addstop>⊕ Add Stop</span></div><div id=stops></div><div class=fg>'+''.join(F(n,f'<input class="inp det" type=time>') for n in ['Loading In','Loading Out','Unloading In','Unloading Out'])+'</div>'
    b+='<div class=sbar><span>Permits'+('' if A else ' &amp; Valuation')+'</span></div><div class=fg>'+F('Permit Numbers (optional)',I('f_permits'))+('' if A else F('Declared Valuation (optional)',I('f_decl','$')))+'</div><div class=vis>PDF prints: OSOW JSA REQUIRED FOR ALL PERMIT LOADS</div>'
    b+='<div class=sbar><span>Signatures</span></div><div class=fg style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">'
    for n in ['Shipper','Driver','Consignee']:
        b+=f'<div><label class=lbl2>{n} signature</label><div class=sigw><canvas class=sig data-who="{n}"></canvas><span class="btn sm clr">Clear</span></div><input class="inp signame" placeholder="Print name" style="margin-top:6px"><input class="inp sigdate" type=date style="margin-top:6px"></div>'
    b+='</div><div class=sbar><span>Consignee Stamp / Label</span></div><input type=file accept="image/*" capture=environment id=f_stamp><div id=stampprev></div>'
    b+='<div class=actions><span class="btn" id=btnsave>💾 Save</span><span class="btn dark" id=btnpdf>📄 Generate PDF</span><span class="btn primary" id=btnmail>✉ Email to customer</span><a href=# class="btn viewterms">View terms and conditions</a></div></form>'
    return b
page('job-214.html','Job #214 Waybills','<h2 style="margin:4px 0">Job #214 — Rig 101 · Sample Drilling Co.</h2><div class=vis>Sample Lease #4H (Pecos, TX) → Sample Ranch Unit 12 #1 (Monahans, TX) · 331 Jourdanton</div><div class=tabs><a href=#>Job Details</a><a href=#>Resources</a><a href=#>Time Records</a><a class=on href=#>Waybills</a><a href=#>Summary</a></div><div class=sbar><span>Waybills</span><span class="btn sm primary" id=newwb>+ New Waybill</span></div><div class=tw><table class=grid id=joblist><thead><tr><th>Waybill #</th><th>Date</th><th>Driver</th><th>Equipment</th><th>Route</th><th class=num>Miles</th><th class=num>Loads</th><th></th></tr></thead><tbody></tbody></table></div><div id=formwrap>'+form(True)+'</div>','Jobs')
page('forms-waybill.html','Forms > Waybill','<div class=vis>Forms › Waybill</div>'+form(False),'Forms')
flt='<div class="filters fg">'+''.join(F(n,S(i)) for n,i in [('Customer','r_cust'),('Personnel','r_pers'),('Job','r_job'),('Equipment Type','r_type'),('Equipment ID','r_eq')])+F('From',I('r_d1',t='date'))+F('To',I('r_d2',t='date'))+'</div>'
page('report.html','Waybills report','<div class=sbar><span>Waybills Report</span><span class="btn sm" id=r_clear>Clear filters</span><span class="btn sm won" id=r_xls>⤓ Export to Excel</span></div>'+flt+'<div class=tw style="margin-top:12px"><table class=grid id=rep><thead><tr><th>Waybill #</th><th>Job #</th><th>Equipment Type</th><th>Equipment ID</th><th>Date</th><th>Employee</th><th>Customer</th><th class=num>Equipment Hours</th><th class=num>Equipment Miles</th><th class=num>Loads</th><th class=num>Loaded Miles</th><th>PDF</th></tr></thead><tbody></tbody><tfoot></tfoot></table></div>','Reports',extra='tfoot td{font-weight:700;background:#fafaf8}')
page('terms.html','Terms and Conditions','<div style="background:#fff;padding:24px;border-radius:8px;max-width:820px;margin:auto" id=tonly></div>')
page('index.html','Waybill mockup','<h2>Tracker V1 — Waybill mockup</h2><p class=vis>Clickable mockup with fake data. Rig move waybills live inside a job; standalone waybills live under Forms. Both share one record, the Waybills report and the PDF.</p><div class=cards>'+''.join(f'<a class=card2 href="{h}?v={V}"><b>{t}</b><p class=vis>{d}</p></a>' for t,h,d in [('Job #214 › Waybills','job-214.html','Waybill list plus New Waybill (rig move), prefilled from the job'),('Forms › Waybill','forms-waybill.html','Standalone driver waybill with shipper/consignee blocks and charges'),('Waybills report','report.html','Filters, totals, PDF per row, Export to Excel'),('PDF preview','pdf.html','Page 1 Bill of Lading + page 2 Terms and Conditions'),('Terms and Conditions','terms.html','Page 2 text shown on every waybill')])+'</div>')
# PDF preview
